// Написан autotest-writer вручную (замер строк через Range). spec: .qa/e2e/specs/chat-personal.md 2.2; кейс .qa/tests/chat-personal/CHAT-POL-02.
// Пара new01↔new02 — как в new01-new02-chat.spec.ts. Блок снимается всегда (в теле и в finally).
// Селекторы меню/окон — с живого сайта 12.11 (#d6881a); «без перезагрузки» и замер «0011?» на живой странице не проверены.
import { test, expect } from '../../fixtures';
import type { Locator, Page } from '@playwright/test';
import { saveSession } from '../_shared/session';
import { N2, phone, openChat } from './chat-personal-helpers';

// Сколько строк занимает подстрока phrase внутри текста элемента (по прямоугольникам Range).
async function linesOf(loc: Locator, phrase: string): Promise<number> {
  return loc.evaluate((el, phrase) => {
    const walker = document.createTreeWalker(el, NodeFilter.SHOW_TEXT);
    let n: Node | null;
    while ((n = walker.nextNode())) {
      const t = n.textContent ?? '';
      const i = t.indexOf(phrase);
      if (i < 0) continue;
      const range = document.createRange();
      range.setStart(n, i);
      range.setEnd(n, i + phrase.length);
      const tops = new Set(Array.from(range.getClientRects()).filter((r) => r.width > 0).map((r) => Math.round(r.top)));
      return tops.size;
    }
    return -1;
  }, phrase);
}

async function unblock(p: Page) {
  await p.goto('/blocked-users');
  await expect(p.getByText('משתמשים חסומים').first()).toBeVisible();
  const btn = p.getByRole('button', { name: `ביטול חסימה ${N2}` });
  await expect(btn.or(p.getByText('אין משתמשים חסומים'))).toBeVisible();
  if (!(await btn.count())) return null;
  const w = p.waitForResponse((r) => /block/i.test(r.url()) && !['GET', 'HEAD', 'OPTIONS'].includes(r.request().method()));
  await btn.click();
  const dlg = p.getByRole('dialog');
  const first = await Promise.race([w.then(() => 'sent' as const), dlg.waitFor().then(() => 'dialog' as const)]);
  let titleLines: number | null = null;
  if (first === 'dialog') {
    const title = dlg.getByText(`לבטל את החסימה של ${N2}?`);
    await expect(title).toBeVisible();
    titleLines = await linesOf(title, `${N2}?`);
    await dlg.getByRole('button', { name: 'לבטל חסימה', exact: true }).click();
  }
  expect((await w).ok(), 'запрос снятия блока 2xx').toBeTruthy();
  await expect(p.getByText('אין משתמשים חסומים')).toBeVisible();
  return titleLines;
}

test.describe('Личный чат: полировка блока (#75e74c)', () => {
  test.describe.configure({ mode: 'serial', timeout: 180_000 });

  test('Блок из чата: «QA П2 0011» пропадает из списка без обновления; окна «לחסום את QA П2 0011?» / «לבטל את החסימה של QA П2 0011?» — «0011?» на одной строке @iphone @data (#75e74c)', async ({ asUser }) => {
    const p = await asUser('new01');
    let blocked = false;
    try {
      await phone(p);
      await openChat(p, N2);
      await p.getByRole('button', { name: "פעולות על הצ'אט" }).click();
      await p.getByRole('dialog').getByRole('button', { name: new RegExp(`חסימת ${N2}`) }).click();
      const blockTitle = p.getByRole('dialog').getByText(`לחסום את ${N2}?`);
      await expect(blockTitle).toBeVisible();
      expect(await linesOf(blockTitle, `${N2}?`), '«QA П2 0011?» в окне блокировки — одна строка (п. 1)').toBe(1);

      const w = p.waitForResponse((r) => /block/i.test(r.url()) && !['GET', 'HEAD', 'OPTIONS'].includes(r.request().method()));
      blocked = true;
      await p.getByRole('dialog').getByRole('button', { name: 'לחסום', exact: true }).click();
      expect((await w).ok(), 'запрос блокировки 2xx').toBeTruthy();

      // Без page.goto/reload: приложение возвращает в список, строки «QA П2 0011» нет (п. 2).
      await expect(p.getByRole('dialog')).toHaveCount(0);
      await p.waitForURL(/\/matches|\/messages|\/chats/, { timeout: 15_000 });
      await expect(p.getByText('הודעות', { exact: true }).first()).toBeVisible();
      await expect(p.getByText(N2, { exact: true })).toHaveCount(0);

      // Разблокировка: заголовок окна — «QA П2 0011?» одной строкой, «?» не начинает строку (п. 1).
      const lines = await unblock(p);
      blocked = false;
      if (lines !== null) expect(lines, '«QA П2 0011?» в окне разблокировки — одна строка').toBe(1);
      await expect(async () => {
        await p.goto('/matches');
        await expect(p.getByText(N2, { exact: true }).last()).toBeVisible({ timeout: 10_000 });
      }).toPass({ timeout: 60_000 });
    } finally {
      let err: unknown;
      if (blocked) await unblock(p).catch((e) => (err = e));
      await saveSession(p, 'new01');
      if (err) throw new Error(`НЕ снят блок new01→new02: сними вручную (new01 → הגדרות → משתמשים חסומים → ביטול חסימה). ${err}`);
    }
  });
});
